		case "word":
			return `word:${content.thaiWord}`;
		case "sentence":
			return `sentence:${content.sentenceId}`;
		case "tone":
			return `tone:${content.thaiWord}`;
		default: {
			const _never: never = content;
			throw new Error(`unhandled game item content: ${JSON.stringify(_never)}`);
		}
	}
}

